#!/usr/bin/env python3
"""Generate the hosted-run binding texts for Math-#447 from runs447.json (collected read-only) and the locally verified merge
identity. Refuses unless every run is completed; prints the PR-body line and writes the #307 comment. C422-E1: every run mention
names the PR head AND the actual tested merge commit. Artifacts: GitHub's digest only, bytes not downloaded (redirect refused)."""
import json, sys
from pathlib import Path
S = Path('<SCRATCH>')
HEAD = '077a168ba9fe3a0888c2d1988f85511c30ca9484'; MERGE = '9ad2639cac8e188eeea3f0d97fd0c48a7de95288'; BASE = '9fb0a4a06900da5cc3f9126f30e117a747df1587'
TREE = '7534b393b3fad12019bfbd44b60606b14f55dce6'
runs = json.loads((S / 'lvs/r7/runs447.json').read_text())
assert all(r['status'] == 'completed' for r in runs), [(r['run'], r['status']) for r in runs]
assert all(r['head_sha'] == HEAD and r['event'] == 'pull_request' and r['attempt'] == 1 for r in runs)
by = {r['name'].split(' (')[0]: r for r in runs}
stmt = by['Lean statement specifications']; prf = by['Lean statement proofs']; rep = by['Downstream hard-gate exact replay']
def arts(r): return '; '.join(f"artifact `{a['name']}` (id {a['id']}, {a['size']} B, GitHub digest `{a['digest']}`)" for a in r['artifacts']) or 'no artifact'
def jobs(r): return ', '.join(f"{j['name']} {j['conclusion']}" for j in r['jobs'])
merge_clause = (f'actual tested merge `{MERGE}` (= `refs/pull/447/merge` at run time, parents `{BASE[:8]}` and `{HEAD[:8]}`, tree `{TREE[:8]}` = the head\'s tree, '
                'verified locally from the fetched ref: the tested merge has exactly the head\'s tree)')
line = (f"the three pull_request runs on PR head `{HEAD[:8]}`, {merge_clause}, all attempt 1: "
        f"`lean-specifications.yml` run {stmt['run']} **{stmt['conclusion']}** (job {jobs(stmt)}; fresh build, leanchecker, `#check`/`#print axioms`, environment audit, negative controls; {arts(stmt)}); "
        f"`lean-specification-proofs.yml` run {prf['run']} **{prf['conclusion']}** (job {jobs(prf)}; the proof packet rebuilt against the appended statement module; {arts(prf)}); "
        f"downstream hard-gate exact replay run {rep['run']} **{rep['conclusion']}** (jobs {jobs(rep)}; {arts(rep)}). "
        "Artifact bytes were not downloaded here (the API redirects to blob storage, which this session's client refuses); the digests are GitHub's. "
        "A green run is a record of a computation about the formal objects: it is not a review, not an alignment, not an acceptance, and it moves no label.")
(S / 'lvs/r7/hosted_runs_line.md').write_text(line + '\n')
ok = all(r['conclusion'] == 'success' for r in runs)
comment = (f"**Math-#447 hosted runs bound (head `{HEAD[:8]}`, stacked on #445 `{BASE[:8]}`): {'all three green' if ok else 'NOT all green, see below'}.** "
           "Anthropic Claude, session `session_01Cz7WZybv8znP64SpPj6sWY`. Organizational-independence credit 0. Scientific effect NONE.\n\n"
           f"- **Runs:** {line}\n"
           "- **What that means and does not:** the appended statement module elaborates, passes the kernel-side audit of the statement gate (statements only) and the proof packet still builds and checks against it; every new declaration stays `specified`, nothing is proved, no inhabitant exists, no claim-level label moves, alignment PENDING_INDEPENDENT_REVIEW. The PR body carries the same binding.\n"
           "- **Next:** a distinct final source reviewer (the appended block and the three register rows against the design packet) and an integrator for #445 then #447; I never mark ready or merge. Recovery checkpoint follows with `runs447.json` and this binding.\n\n"
           "---\n_Generated by [Claude Code](https://claude.ai/code)_\n")
(S / 'lvs/r7/bind_comment447.md').write_text(comment)
json.dump({'body': comment}, open(S / 'lvs/r7/bind_comment447_payload.json', 'w'))
print('ALL GREEN' if ok else 'NOT GREEN'); print(line[:400])
